<script setup lang="ts">
import type { FrameCandle, ActiveTrade, Decision } from './types';
import { coin, PAIR_COLORS } from './types';

defineProps<{
  pair: string;
  candle: FrameCandle | null;
  trade: ActiveTrade | null;
  decision: Decision | null;
}>();
</script>

<template>
  <div class="p-3 rounded-sm mt-2" :style="{ background: '#161b22', border: trade ? '2px solid #64ffda' : '1px solid #30363d' }">
    <!-- Header -->
    <div class="flex items-center gap-1 mb-1 flex-wrap">
      <span v-if="trade" class="px-2 py-0.5 rounded-sm text-sm font-bold"
        style="background: #64ffda15; border: 1px solid #64ffda; color: #64ffda; animation: pulse 2s infinite;">
        {{ trade.side.toUpperCase() }} OPEN
      </span>
      <span v-if="candle?.signal" class="px-2 py-0.5 rounded-sm text-sm font-bold"
        :style="{
          background: candle.signal.type === 'entry' ? '#23863633' : (candle.signal.win ? '#23863633' : '#f8514933'),
          color: candle.signal.type === 'entry' ? '#4caf50' : (candle.signal.win ? '#4caf50' : '#f85149'),
          border: '1px solid ' + (candle.signal.type === 'entry' ? '#238636' : (candle.signal.win ? '#238636' : '#f85149')),
        }">
        {{ candle.signal.type === 'entry' ? 'IN' : 'OUT' }}
        {{ candle.signal.tag }}
        {{ candle.signal.profit_pct != null ? candle.signal.profit_pct + '%' : '' }}
      </span>
    </div>

    <!-- Active trade P&L -->
    <div v-if="trade" class="mb-1 px-3 py-2 rounded-sm" style="background: #0d1117; font-family: monospace;">
      <div class="flex justify-between items-center mb-1">
        <span class="text-base text-muted-color">{{ trade.tag }}</span>
        <span class="text-xl font-bold px-3 py-1 rounded-sm"
          :style="{
            color: trade.current_profit_pct >= 0 ? '#4caf50' : '#f85149',
            background: trade.current_profit_pct >= 0 ? '#23863622' : '#f8514922',
          }">
          {{ trade.current_profit_pct >= 0 ? 'WIN' : 'LOSE' }}
          {{ trade.current_profit_pct >= 0 ? '+' : '' }}{{ trade.current_profit_pct }}%
          <span style="font-size: 14px; opacity: 0.8;">
            (${{ (40 * trade.current_profit_pct / 100).toFixed(2) }})
          </span>
        </span>
      </div>
      <div class="flex justify-between text-base text-muted-color">
        <span>Entry: <b style="color: #e0e0e0">{{ trade.entry_price }}</b></span>
        <span>Now: <b style="color: #e0e0e0">{{ candle?.close }}</b></span>
        <span>Diff: <b :style="{ color: trade.current_profit_pct >= 0 ? '#4caf50' : '#f85149' }">
          {{ candle && trade ? (candle.close - trade.entry_price >= 0 ? '+' : '') + (candle.close - trade.entry_price).toFixed(4) : '' }}
        </b></span>
      </div>
    </div>

    <!-- Data -->
    <div style="font-family: monospace; font-size: 15px; line-height: 2;">
      <div class="flex justify-between">
        <span class="text-muted-color">Close <span style="opacity:0.5;font-size:11px">last price</span></span>
        <span class="font-bold">{{ candle?.close }}</span>
      </div>
      <div class="flex justify-between">
        <span class="text-muted-color">Pair Z <span style="opacity:0.5;font-size:11px">per-pair mean-reversion</span></span>
        <span class="font-bold" :style="{ color: Math.abs(candle?.pair_z || 0) > 1 ? ((candle?.pair_z || 0) > 0 ? '#f85149' : '#4caf50') : '#8b949e' }">{{ candle?.pair_z }}</span>
      </div>
      <div class="flex justify-between">
        <span class="text-muted-color">Spread Z <span style="opacity:0.5;font-size:11px">group A vs B divergence</span></span>
        <span class="font-bold" :style="{ color: Math.abs(candle?.spread_z || 0) > 1 ? ((candle?.spread_z || 0) > 0 ? '#f85149' : '#4caf50') : '#8b949e' }">{{ candle?.spread_z }}</span>
      </div>
    </div>

    <!-- Decision tree -->
    <div v-if="decision" class="mt-2 p-2 rounded-sm" style="font-size: 13px; font-family: monospace; background: #0d1117;">
      <div class="flex items-center gap-2 mb-2">
        <span class="px-2 py-1 rounded-sm text-base font-bold"
          :style="{ background: decision.mode === 'exit' ? '#64ffda15' : '#21262d', color: decision.mode === 'exit' ? '#64ffda' : '#8b949e', border: '1px solid ' + (decision.mode === 'exit' ? '#64ffda44' : '#30363d') }">
          {{ decision.mode === 'exit' ? 'EXIT CHECK' : 'ENTRY CHECK' }}
        </span>
        <span class="px-2 py-1 rounded-sm text-base font-bold"
          :style="{
            background: decision.signal === 'WAIT' || decision.signal === 'HOLD' ? '#21262d' : '#ffd54f22',
            color: decision.signal === 'STOP LOSS' ? '#f85149' : decision.signal === 'WAIT' || decision.signal === 'HOLD' ? '#484f58' : '#ffd54f',
            border: '1px solid ' + (decision.signal === 'STOP LOSS' ? '#f85149' : decision.signal === 'WAIT' || decision.signal === 'HOLD' ? '#30363d' : '#ffd54f44'),
          }">
          → {{ decision.signal }}
        </span>
      </div>
      <div class="flex gap-2 flex-wrap">
        <span v-for="cond in decision.conditions" :key="cond.name"
          class="px-2 py-1 rounded-sm text-base"
          :style="{ background: cond.ok ? '#23863633' : '#21262d', color: cond.ok ? '#4caf50' : '#484f58', border: '1px solid ' + (cond.ok ? '#23863644' : '#30363d') }">
          {{ cond.name }} {{ cond.ok ? '✓' : '✗' }} <span style="opacity: 0.6">{{ cond.value }}</span>
        </span>
      </div>
    </div>
  </div>
</template>
