<script setup lang="ts">
import { use } from 'echarts/core';
import { LineChart, CandlestickChart } from 'echarts/charts';
import { GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, DataZoomComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import VChart from 'vue-echarts';

import TransportBar from '@/components/monitor/TransportBar.vue';
import PairCard from '@/components/monitor/PairCard.vue';
import TradeSummary from '@/components/monitor/TradeSummary.vue';
import { buildBtcChart, buildPairChart, buildEquityChart } from '@/components/monitor/chartBuilders';
import type { PairRawData, ActiveTrade, Decision, FrameCandle, Signal } from '@/components/monitor/types';
import { PAIRS, GROUP_A, GROUP_B, PAIR_COLORS, coin } from '@/components/monitor/types';

use([CanvasRenderer, LineChart, CandlestickChart, GridComponent, TooltipComponent, LegendComponent, MarkLineComponent, DataZoomComponent]);

const CTRL = `${window.location.protocol}//${window.location.hostname}:8084`;

// ── State ──
const saved = JSON.parse(localStorage.getItem('monitorCtrl') || '{}');
const browseStart = ref(saved.start || '2026-04-01');
const browseEnd = ref(saved.end || '2026-05-01');
const frameIndex = ref(0);
const lastRendered = ref(-1);
const totalFrames = ref(0);
const currentTimestamp = ref('');
const playing = ref(false);
const playInterval = ref<number | null>(null);
const playSpeed = ref(saved.speed || 500);
const loading = ref(false);
const visibleCandles = ref(saved.visible || 100);

// ── Data stores ──
const rawData = reactive<Record<string, PairRawData>>({});
const equityRaw = reactive<{ equity: number[]; initial: number }>({ equity: [], initial: 100 });
const chartLabels = reactive<Record<string, string[]>>({});
const chartOhlc = reactive<Record<string, number[][]>>({});
const chartPrice = reactive<Record<string, number[]>>({});
const chartPairZ = reactive<Record<string, number[]>>({});
const chartSpreadZ = reactive<Record<string, number[]>>({});
const chartEquity = reactive<number[]>([]);

function saveLocal() {
  localStorage.setItem('monitorCtrl', JSON.stringify({ start: browseStart.value, end: browseEnd.value, speed: playSpeed.value, visible: visibleCandles.value }));
}

// Visible window: last N candles from current position
function sliceTail<T>(arr: T[]): T[] {
  const n = visibleCandles.value;
  if (n <= 0 || n >= 99999 || arr.length <= n) return arr;
  return arr.slice(arr.length - n);
}

// ── Data loading ──
async function loadAllData() {
  loading.value = true;
  saveLocal();
  totalFrames.value = 0;
  try {
    const resp = await fetch(`${CTRL}/signals?start=${browseStart.value}&end=${browseEnd.value}&timeframe=15m`);
    const data = await resp.json();
    for (const pair of PAIRS) {
      if (data[pair]) { rawData[pair] = data[pair]; if (!totalFrames.value) totalFrames.value = data[pair].labels.length; }
      chartLabels[pair] = []; chartOhlc[pair] = []; chartPrice[pair] = []; chartPairZ[pair] = []; chartSpreadZ[pair] = [];
    }
    if (data._equity) { equityRaw.equity = data._equity.equity; equityRaw.initial = data._equity.initial; }
    chartEquity.length = 0;
  } catch { /* */ }
  frameIndex.value = 0; lastRendered.value = -1; syncToFrame(); loading.value = false;
}

// ── Frame sync (append/truncate) ──
function syncToFrame() {
  const target = frameIndex.value;
  if (target > lastRendered.value) {
    for (let i = lastRendered.value + 1; i <= target; i++) {
      for (const pair of PAIRS) {
        const r = rawData[pair]; if (!r || i >= r.labels.length) continue;
        chartLabels[pair].push(r.labels[i]); chartOhlc[pair].push(r.ohlc[i]);
        chartPrice[pair].push(r.price[i]); chartPairZ[pair].push(r.pair_zscore?.[i] ?? 0);
        chartSpreadZ[pair].push(r.spread_zscore?.[i] ?? 0);
      }
      chartEquity.push(equityRaw.equity[i] ?? equityRaw.initial);
    }
  } else if (target < lastRendered.value) {
    for (const pair of PAIRS) {
      chartLabels[pair].length = target + 1; chartOhlc[pair].length = target + 1;
      chartPrice[pair].length = target + 1; chartPairZ[pair].length = target + 1; chartSpreadZ[pair].length = target + 1;
    }
    chartEquity.length = target + 1;
  }
  lastRendered.value = target;
  const btc = rawData['BTC/USDC:USDC'];
  if (btc && target < btc.labels.length) currentTimestamp.value = btc.labels[target];
}

// ── Transport ──
function stepFrame(d: number) { frameIndex.value = Math.max(0, Math.min(frameIndex.value + d, totalFrames.value - 1)); syncToFrame(); }
function seekFrame(i: number) { frameIndex.value = Math.max(0, Math.min(i, totalFrames.value - 1)); syncToFrame(); }
function togglePlay() {
  if (playing.value) { if (playInterval.value) clearInterval(playInterval.value); playInterval.value = null; playing.value = false; }
  else { playing.value = true; playInterval.value = window.setInterval(() => { if (frameIndex.value >= totalFrames.value - 1) { togglePlay(); return; } stepFrame(1); }, playSpeed.value); }
}
function updateSpeed(s: number) { playSpeed.value = s; saveLocal(); }

// ── Computed: charts (sliced to visible window) ──
const btcChart = computed(() => buildBtcChart(sliceTail(chartLabels['BTC/USDC:USDC'] || []), sliceTail(chartOhlc['BTC/USDC:USDC'] || [])));
function pairChartOpt(pair: string) {
  const n = visibleCandles.value;
  const labels = sliceTail(chartLabels[pair] || []);
  const prices = sliceTail(chartPrice[pair] || []);
  const pz = sliceTail(chartPairZ[pair] || []);
  const sz = sliceTail(chartSpreadZ[pair] || []);
  // Offset signals to match sliced window
  const totalLen = chartLabels[pair]?.length || 0;
  const offset = Math.max(0, totalLen - n);
  const signals = (rawData[pair]?.signals || [])
    .filter(s => s.index >= offset && s.index <= frameIndex.value)
    .map(s => ({ ...s, index: s.index - offset }));
  const ranges = (rawData[pair]?.trade_ranges || [])
    .filter(tr => tr.exit_index >= offset && tr.entry_index <= frameIndex.value)
    .map(tr => ({ ...tr, entry_index: Math.max(0, tr.entry_index - offset), exit_index: Math.min(tr.exit_index - offset, labels.length - 1) }));
  return buildPairChart(pair, labels, prices, pz, sz, signals, ranges, labels.length - 1, PAIR_COLORS[pair] || '#8b949e');
}
const equityLabels = computed(() => {
  // Use first pair that has labels
  for (const pair of PAIRS) {
    if (chartLabels[pair]?.length) return chartLabels[pair];
  }
  return [];
});
const equityChart = computed(() => buildEquityChart(sliceTail(equityLabels.value), sliceTail([...chartEquity]), equityRaw.initial));

// ── Computed: frame data ──
const currentCandles = computed<Record<string, FrameCandle>>(() => {
  const r: Record<string, FrameCandle> = {};
  for (const pair of PAIRS) {
    const raw = rawData[pair]; if (!raw || frameIndex.value >= raw.ohlc.length) continue;
    const o = raw.ohlc[frameIndex.value];
    let sig: Signal | null = null;
    for (const s of raw.signals || []) { if (s.index === frameIndex.value) { sig = s; break; } }
    r[pair] = { open: o[0], close: o[1], low: o[2], high: o[3], pair_z: raw.pair_zscore?.[frameIndex.value] ?? 0, spread_z: raw.spread_zscore?.[frameIndex.value] ?? 0, signal: sig };
  }
  return r;
});

const activeTrades = computed<Record<string, ActiveTrade>>(() => {
  const r: Record<string, ActiveTrade> = {};
  for (const pair of PAIRS) {
    const raw = rawData[pair]; if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (frameIndex.value >= tr.entry_index && frameIndex.value <= tr.exit_index) {
        const cp = raw.price[frameIndex.value] || tr.entry_price;
        const profit = tr.side === 'long' ? (cp - tr.entry_price) / tr.entry_price * 100 : (tr.entry_price - cp) / tr.entry_price * 100;
        r[pair] = { ...tr, current_profit_pct: Math.round(profit * 100) / 100 }; break;
      }
    }
  }
  return r;
});

const decisions = computed<Record<string, Decision>>(() => {
  const r: Record<string, Decision> = {};
  const cfg = { z: 1.8, pz: 0.5, scalp: 0.004, sl: -0.10 };
  for (const pair of PAIRS) {
    if (pair.startsWith('BTC/')) continue;
    const raw = rawData[pair]; if (!raw || frameIndex.value >= raw.labels.length) continue;
    const pz = raw.pair_zscore[frameIndex.value], sz = raw.spread_zscore[frameIndex.value];
    const vol = raw.vol_ok?.[frameIndex.value] ?? false;
    const isA = GROUP_A.includes(pair);
    const trade = activeTrades.value[pair];

    if (trade) {
      const p = trade.current_profit_pct / 100, isL = trade.side === 'long';
      const sl_hit = p <= cfg.sl, scalp = p >= cfg.scalp && ((isL && pz > 0) || (!isL && pz < 0)), roi = p >= 0.005;
      r[pair] = { mode: 'exit', signal: sl_hit ? 'STOP LOSS' : scalp ? 'SCALP EXIT' : roi ? 'ROI EXIT' : 'HOLD', conditions: [
        { name: 'profit', ok: p > 0, value: `${trade.current_profit_pct}%` },
        { name: 'z-cross-0', ok: scalp, value: isL ? `pz=${pz.toFixed(2)} ${pz > 0 ? '>0' : '<0'}` : `pz=${pz.toFixed(2)} ${pz < 0 ? '<0' : '>0'}` },
        { name: 'stoploss', ok: !sl_hit, value: `${(p * 100).toFixed(1)}% vs ${cfg.sl * 100}%` },
        { name: 'roi', ok: roi, value: `${(p * 100).toFixed(1)}%` },
      ]};
    } else {
      let sp_ok = false, pz_ok = false, sig = 'WAIT';
      if (isA) { sp_ok = sz < -cfg.z; pz_ok = pz < -cfg.pz; if (sp_ok && pz_ok && vol) sig = 'LONG'; }
      else { const sh = sz < -cfg.z && pz > cfg.pz, lo = sz > cfg.z && pz < -cfg.pz; sp_ok = Math.abs(sz) > cfg.z; pz_ok = sh || lo; if (sh && vol) sig = 'SHORT'; else if (lo && vol) sig = 'LONG'; }
      r[pair] = { mode: 'entry', signal: sig, conditions: [
        { name: 'spread', ok: sp_ok, value: `sz=${sz.toFixed(2)}` },
        { name: 'pair_z', ok: pz_ok, value: `pz=${pz.toFixed(2)}` },
        { name: 'vol', ok: vol, value: vol ? 'OK' : 'low' },
      ]};
    }
  }
  return r;
});

const openCount = computed(() => Object.keys(activeTrades.value).length);
const tradeStats = computed(() => {
  let w = 0, l = 0;
  for (const pair of PAIRS) { for (const s of rawData[pair]?.signals || []) { if (s.type === 'exit' && s.index <= frameIndex.value) { s.win ? w++ : l++; } } }
  return { w, l, pct: w + l > 0 ? ((w / (w + l)) * 100).toFixed(0) : '0' };
});
const progressPct = computed(() => totalFrames.value > 1 ? (frameIndex.value / (totalFrames.value - 1) * 100).toFixed(1) : '0');

// Trade history — all closed trades up to current frame
interface TradeHistoryItem {
  pair: string;
  side: string;
  tag: string;
  exit_tag: string;
  entry_label: string;
  exit_label: string;
  entry_index: number;
  exit_index: number;
  entry_price: number;
  exit_price: number;
  profit_pct: number;
  win: boolean;
  duration: number;
}

const tradeHistory = computed<TradeHistoryItem[]>(() => {
  const trades: TradeHistoryItem[] = [];
  for (const pair of PAIRS) {
    const raw = rawData[pair];
    if (!raw?.trade_ranges) continue;
    for (const tr of raw.trade_ranges) {
      if (tr.profit_pct !== null && tr.exit_index <= frameIndex.value) {
        trades.push({
          pair,
          side: tr.side,
          tag: tr.tag,
          exit_tag: tr.exit_tag,
          entry_label: raw.labels[tr.entry_index] || '',
          exit_label: raw.labels[tr.exit_index] || '',
          entry_index: tr.entry_index,
          exit_index: tr.exit_index,
          entry_price: tr.entry_price,
          exit_price: raw.price[tr.exit_index] || 0,
          profit_pct: tr.profit_pct,
          win: tr.win ?? false,
          duration: tr.exit_index - tr.entry_index,
        });
      }
    }
  }
  trades.sort((a, b) => a.exit_label.localeCompare(b.exit_label));
  return trades;
});

const historyTotals = computed(() => {
  const h = tradeHistory.value;
  const wins = h.filter(t => t.win).length;
  const losses = h.length - wins;
  const totalProfit = h.reduce((s, t) => s + t.profit_pct, 0);
  const avgProfit = h.length > 0 ? totalProfit / h.length : 0;
  const avgDuration = h.length > 0 ? h.reduce((s, t) => s + t.duration, 0) / h.length : 0;
  const best = h.length > 0 ? Math.max(...h.map(t => t.profit_pct)) : 0;
  const worst = h.length > 0 ? Math.min(...h.map(t => t.profit_pct)) : 0;
  return { total: h.length, wins, losses, totalProfit: totalProfit.toFixed(2), avgProfit: avgProfit.toFixed(2), avgDuration: Math.round(avgDuration), best: best.toFixed(2), worst: worst.toFixed(2) };
});

// Expand/collapse
const expandBtc = ref(true);
const expandPair = reactive<Record<string, boolean>>({});
for (const p of PAIRS) expandPair[p] = true;
const expandEquity = ref(true);
const expandHistory = ref(true);

// ── Strategy name + timeframe ──
const strategyName = ref('');
const strategyTimeframe = ref('');
async function fetchStrategyName() {
  try {
    const base = window.location.origin;
    const loginResp = await fetch(`${base}/api/v1/token/login`, {
      method: 'POST',
      headers: { 'Authorization': 'Basic ' + btoa('freqtrader:freqtrader') },
    });
    if (loginResp.ok) {
      const { access_token } = await loginResp.json();
      const cfgResp = await fetch(`${base}/api/v1/show_config`, {
        headers: { 'Authorization': `Bearer ${access_token}` },
      });
      if (cfgResp.ok) {
        const cfg = await cfgResp.json();
        strategyName.value = cfg.strategy || '';
        strategyTimeframe.value = cfg.timeframe || '';
      }
    }
  } catch { /* */ }
}

onMounted(() => { fetchStrategyName(); loadAllData(); });
onUnmounted(() => { if (playInterval.value) clearInterval(playInterval.value); });
</script>

<template>
  <div class="flex flex-col gap-3 p-4 h-full overflow-y-auto">
    <!-- Transport -->
    <TransportBar
      :total-frames="totalFrames" :frame-index="frameIndex" :current-timestamp="currentTimestamp"
      :playing="playing" :play-speed="playSpeed" :progress-pct="progressPct"
      :browse-start="browseStart" :browse-end="browseEnd" :loading="loading"
      :visible-candles="visibleCandles" :strategy-name="strategyName" :strategy-timeframe="strategyTimeframe"
      @seek="seekFrame" @step="stepFrame" @toggle-play="togglePlay" @load="loadAllData"
      @update:browse-start="browseStart = $event" @update:browse-end="browseEnd = $event"
      @update:play-speed="updateSpeed"
      @update:visible-candles="(v: number) => { visibleCandles = v || 99999; saveLocal(); }"
    />

    <!-- Trade Summary Bar -->
    <div v-if="totalFrames > 0">
      <TradeSummary
        :open-count="openCount" :wins="tradeStats.w" :losses="tradeStats.l" :win-pct="tradeStats.pct"
        :equity-current="equityChart.current" :profit-pct="equityChart.profitPct"
        :profit-positive="Number(equityChart.profit) >= 0"
      />
    </div>

    <!-- BTC — collapsible chart, card always visible -->
    <div v-if="chartLabels['BTC/USDC:USDC']?.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandBtc = !expandBtc">
        <span style="color: #ffd54f; font-size: 14px">{{ expandBtc ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-base font-bold" style="color: #ffd54f">BTC/USDC</span>
        <span style="opacity:0.5;font-size:12px" class="text-muted-color">— regime reference (not traded)</span>
        <span class="text-base text-muted-color ms-auto">{{ currentCandles['BTC/USDC:USDC']?.close }}</span>
      </div>
      <div v-show="expandBtc" class="px-3 pb-3">
        <VChart :option="btcChart" style="height: 250px" autoresize />
        <PairCard :pair="'BTC/USDC:USDC'" :candle="currentCandles['BTC/USDC:USDC'] || null" :trade="null" :decision="null" />
      </div>
    </div>

    <!-- Group Charts -->
    <div class="grid grid-cols-2 gap-3">
      <div v-for="(group, gi) in [GROUP_A, GROUP_B]" :key="gi" class="flex flex-col gap-3">
        <div class="px-3 py-2 flex items-center gap-2 font-bold text-base rounded-md"
          :style="{ background: gi === 0 ? '#0f2d1f' : '#1a1a2e', border: `1px solid ${gi === 0 ? '#238636' : '#7c4dff'}` }">
          <span :style="{ color: gi === 0 ? '#4caf50' : '#b388ff' }">Group {{ gi === 0 ? 'A' : 'B' }}</span>
          <span class="text-muted-color text-base ms-auto">{{ gi === 0 ? 'LONG only' : 'SHORT + LONG' }}</span>
        </div>
        <div v-for="pair in group" :key="pair" class="rounded-md border"
          :style="{ borderColor: gi === 0 ? '#238636' : '#7c4dff', background: gi === 0 ? '#0a1612' : '#0d0d1a' }">

          <!-- Trade/Order info — ALWAYS visible -->
          <div class="px-3 pt-3">
            <PairCard :pair="pair" :candle="currentCandles[pair] || null" :trade="activeTrades[pair] || null" :decision="decisions[pair] || null" />
          </div>

          <!-- Chart header — clickable to expand/collapse -->
          <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandPair[pair] = !expandPair[pair]">
            <span :style="{ color: gi === 0 ? '#4caf50' : '#b388ff', fontSize: '14px' }">{{ expandPair[pair] ? '\u25BC' : '\u25B6' }}</span>
            <span class="font-bold text-lg" :style="{ color: gi === 0 ? '#4caf50' : '#b388ff' }">{{ coin(pair) }} Chart</span>
            <span class="text-lg text-muted-color ms-auto">{{ currentCandles[pair]?.close }}</span>
          </div>

          <!-- Chart — collapsible -->
          <div v-show="expandPair[pair]" class="px-3 pb-3">
            <VChart v-if="chartLabels[pair]?.length" :option="pairChartOpt(pair)" style="height: 300px" autoresize />
          </div>
        </div>
      </div>
    </div>

    <!-- Equity Curve — collapsible, at bottom -->
    <div v-if="chartEquity.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandEquity = !expandEquity">
        <span style="color: #4caf50; font-size: 14px">{{ expandEquity ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #4caf50">Equity Curve</span>
        <span style="opacity:0.5;font-size:13px" class="text-muted-color">— cumulative P&L across all pairs</span>
        <span class="text-lg font-bold ms-auto" :style="{ color: Number(equityChart.profit) >= 0 ? '#4caf50' : '#f85149' }">
          ${{ equityChart.current.toFixed(1) }} ({{ Number(equityChart.profit) >= 0 ? '+' : '' }}{{ equityChart.profitPct }}%)
        </span>
      </div>
      <div v-show="expandEquity" class="px-3 pb-3">
        <VChart :option="equityChart.option" style="height: 150px" autoresize />
      </div>
    </div>
    <!-- Trade History -->
    <div v-if="tradeHistory.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
      <div class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none" @click="expandHistory = !expandHistory">
        <span style="color: #58a6ff; font-size: 14px">{{ expandHistory ? '\u25BC' : '\u25B6' }}</span>
        <span class="text-lg font-bold" style="color: #58a6ff">Trade History</span>
        <span style="opacity:0.5;font-size:13px" class="text-muted-color">— all closed trades</span>
        <span class="text-base text-muted-color ms-auto">{{ historyTotals.total }} trades</span>
      </div>
      <div v-show="expandHistory" class="px-3 pb-3">
        <!-- Totals summary -->
        <div class="flex gap-4 mb-3 p-2 rounded-sm" style="background: #0d1117; font-family: monospace; font-size: 14px;">
          <div><span class="text-muted-color">Total:</span> <b>{{ historyTotals.total }}</b></div>
          <div><span class="text-muted-color">W/L:</span> <span style="color:#4caf50">{{ historyTotals.wins }}</span> / <span style="color:#f85149">{{ historyTotals.losses }}</span></div>
          <div><span class="text-muted-color">Win%:</span> <b :style="{ color: parseInt(tradeStats.pct) >= 80 ? '#4caf50' : '#ffd54f' }">{{ tradeStats.pct }}%</b></div>
          <div><span class="text-muted-color">Total P&L:</span> <b :style="{ color: Number(historyTotals.totalProfit) >= 0 ? '#4caf50' : '#f85149' }">{{ Number(historyTotals.totalProfit) >= 0 ? '+' : '' }}{{ historyTotals.totalProfit }}%</b></div>
          <div><span class="text-muted-color">Avg:</span> <b>{{ historyTotals.avgProfit }}%</b></div>
          <div><span class="text-muted-color">Best:</span> <span style="color:#4caf50">+{{ historyTotals.best }}%</span></div>
          <div><span class="text-muted-color">Worst:</span> <span style="color:#f85149">{{ historyTotals.worst }}%</span></div>
          <div><span class="text-muted-color">Avg Dur:</span> {{ historyTotals.avgDuration }} candles</div>
        </div>

        <!-- Table header -->
        <div class="grid gap-1 mb-1 px-2" style="grid-template-columns: 35px 70px 55px 100px 100px 85px 85px 75px 65px 65px 85px; font-size: 12px; font-weight: bold; color: #8b949e; border-bottom: 1px solid #21262d; padding-bottom: 4px;">
          <span>#</span><span>Pair</span><span>Side</span><span>Entry</span><span>Exit</span>
          <span>Entry $</span><span>Exit $</span><span>P&L %</span><span>P&L $</span><span>Dur</span><span>Reason</span>
        </div>

        <!-- Rows -->
        <div style="max-height: 400px; overflow-y: auto;">
          <div v-for="(t, i) in tradeHistory" :key="i"
            class="grid gap-1 px-2 py-1" style="grid-template-columns: 35px 70px 55px 100px 100px 85px 85px 75px 65px 65px 85px; font-size: 13px; font-family: monospace; border-bottom: 1px solid #161b22;"
            :style="{ background: t.win ? '#23863608' : '#f8514908' }">
            <span class="text-muted-color">{{ i + 1 }}</span>
            <span class="font-bold" :style="{ color: PAIR_COLORS[t.pair] || '#8b949e' }">{{ coin(t.pair) }}</span>
            <span :style="{ color: t.side === 'long' ? '#4caf50' : '#f85149' }">{{ t.side.toUpperCase() }}</span>
            <span style="color: #58a6ff; cursor: pointer; text-decoration: underline;" @click="seekFrame(t.entry_index)">{{ t.entry_label }}</span>
            <span style="color: #58a6ff; cursor: pointer; text-decoration: underline;" @click="seekFrame(t.exit_index)">{{ t.exit_label }}</span>
            <span>{{ t.entry_price }}</span>
            <span>{{ t.exit_price }}</span>
            <span class="font-bold" :style="{ color: t.win ? '#4caf50' : '#f85149' }">{{ t.win ? '+' : '' }}{{ t.profit_pct }}%</span>
            <span class="font-bold" :style="{ color: t.win ? '#4caf50' : '#f85149' }">${{ (40 * t.profit_pct / 100).toFixed(2) }}</span>
            <span class="text-muted-color">{{ t.duration }}c</span>
            <span class="text-muted-color">{{ t.exit_tag }}</span>
          </div>
        </div>
